import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        StringTokenizer st = new StringTokenizer(line);
        long n = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());

        long res = solve(n, m);

        StringBuilder sb = new StringBuilder();
        sb.append(res);
        System.out.print(sb.toString());
    }

    static long solve(long n, long m) {
        long pre = 1;
        long M = mod(m);
        long res = 0;
        long ans = M;
        long ans1 = M;

        boolean[] p = getPrimes((int) (n + 10));

        for (long i = 2; i <= n; i++) {
            if (pre <= m && p[(int) i]) {
                pre = pre * i;
            }
            if (pre > m) {
                ans = 0;
            } else {
                ans = mul(ans, m / pre);
            }
            ans1 = mul(ans1, M);
            res = mod(res + ans1 - ans);
        }

        return res;
    }

    static boolean[] getPrimes(int n) {
        boolean[] nums = new boolean[n + 1];
        Arrays.fill(nums, true);
        if (n >= 0) nums[0] = false;
        if (n >= 1) nums[1] = false;

        List<Integer> primes = new ArrayList<>();

        for (int i = 2; i <= n; i++) {
            if (nums[i]) primes.add(i);
            for (int j = 0; j < primes.size() && primes.get(j) <= n / i; j++) {
                nums[primes.get(j) * i] = false;
                if (i % primes.get(j) == 0) break;
            }
        }

        return nums;
    }

    static long mod(long num) {
        if (num >= MOD) {
            return num % MOD;
        } else if (num < 0) {
            return (num % MOD + MOD) % MOD;
        }
        return num;
    }

    static long mul(long a, long b) {
        long aa = mod(a);
        long bb = mod(b);
        return (aa * bb) % MOD;
    }
}
